// From: ReconciliationPolicy (effect-commitment module)
// Corrected: exercises the frozen contract instead of the inert assert!(false)
// scaffold (see ISSUE-CONTRACT-FREEZE).

#[cfg(test)]
mod tests {
    use chrono::Utc;
    use rigorix_engine::capacity_ledger::domain::IdempotencyKey;
    use rigorix_engine::effect_commitment::application::ReconciliationPolicy;
    use rigorix_engine::effect_commitment::domain::{
        CommitmentError, EffectIntent, EffectRecord, EffectState, ObservedOutcome,
        ResolverIdentity, ResolverKind,
    };
    use uuid::Uuid;

    fn intent() -> EffectIntent {
        EffectIntent::new(
            Uuid::from_u128(1),
            Uuid::from_u128(2),
            1,
            IdempotencyKey::new("intent-key"),
            "payments.charge",
            "args-digest",
            "precondition-digest",
            "authority-digest",
        )
    }

    fn ambiguous() -> EffectRecord {
        EffectRecord::begin(intent())
            .mark_ambiguous("response lost", Utc::now())
            .unwrap()
    }

    fn evidence() -> ObservedOutcome {
        ObservedOutcome::committed("receipt-1", "readback-1", Utc::now(), "stripe")
    }

    #[test]
    fn test_reconciliationpolicy_is_defined() {
        let policy = ReconciliationPolicy::new();
        assert_eq!(policy, ReconciliationPolicy);

        // The normative state machine, including the illegal retry edge.
        assert!(policy.is_legal_transition(EffectState::Dispatched, EffectState::Ambiguous));
        assert!(policy.is_legal_transition(EffectState::Ambiguous, EffectState::Committed));
        assert!(policy.is_legal_transition(EffectState::Ambiguous, EffectState::NotCommitted));
        assert!(!policy.is_legal_transition(EffectState::Ambiguous, EffectState::Dispatched));
        assert!(!policy.is_legal_transition(EffectState::Committed, EffectState::Ambiguous));
    }

    #[test]
    fn test_reconciliationpolicy_interacts_with_effectstate() {
        let policy = ReconciliationPolicy::new();
        let record = ambiguous();
        let resolver = ResolverIdentity::new("stripe", ResolverKind::Provider, "readback-1");
        assert!(
            policy
                .authorize_resolution(&record, Some(&evidence()), &resolver)
                .is_ok()
        );

        // Only an ambiguous record can be resolved; a dispatched one must first
        // be marked ambiguous (or settled definitely).
        let dispatched = EffectRecord::begin(intent());
        assert!(matches!(
            policy.authorize_resolution(&dispatched, Some(&evidence()), &resolver),
            Err(CommitmentError::NotAmbiguous { .. })
        ));
    }

    #[test]
    fn test_reconciliationpolicy_interacts_with_observedoutcome() {
        let policy = ReconciliationPolicy::new();
        let record = ambiguous();
        let resolver = ResolverIdentity::new("stripe", ResolverKind::Provider, "readback-1");

        // F3: no evidence, no resolution. Absence of evidence is not evidence of
        // absence and must never become NotCommitted.
        assert!(matches!(
            policy.authorize_resolution(&record, None, &resolver),
            Err(CommitmentError::EvidenceMissing { .. })
        ));
    }

    #[test]
    fn test_reconciliationpolicy_interacts_with_resolveridentity() {
        let policy = ReconciliationPolicy::new();
        let record = ambiguous();
        let evidence = evidence();

        // F4: the dispatching process and the agent are never the resolver.
        for kind in [ResolverKind::DispatchingProcess, ResolverKind::Agent] {
            let resolver = ResolverIdentity::new("bad-resolver", kind, "readback-1");
            assert!(matches!(
                policy.authorize_resolution(&record, Some(&evidence), &resolver),
                Err(CommitmentError::UnauthorizedResolver { .. })
            ));
        }

        // An external operator presenting provider evidence is authorised.
        let operator = ResolverIdentity::new("ops-1", ResolverKind::ExternalOperator, "readback-1");
        assert!(
            policy
                .authorize_resolution(&record, Some(&evidence), &operator)
                .is_ok()
        );
    }
}
